CREATE TABLE IF NOT EXISTS home_fixed_items (id uuid PRIMARY KEY, name text NOT NULL, kind text NOT NULL CHECK (kind IN ('expense', 'income', 'investment')), amount_minor bigint NOT NULL CHECK (amount_minor > 0), owner_id uuid REFERENCES home_users(id) ON DELETE SET NULL, category_id uuid REFERENCES home_categories(id) ON DELETE SET NULL, due_day smallint CHECK (due_day BETWEEN 1 AND 31), starts_on date NOT NULL CHECK (extract(day FROM starts_on) = 1), ends_on date CHECK (ends_on IS NULL OR (extract(day FROM ends_on) = 1 AND ends_on >= starts_on)), sort_order integer NOT NULL DEFAULT 0, created_by uuid REFERENCES home_users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS home_fixed_items_live_idx ON home_fixed_items (starts_on, ends_on);

CREATE TABLE IF NOT EXISTS home_fixed_payments (id uuid PRIMARY KEY, item_id uuid NOT NULL REFERENCES home_fixed_items(id) ON DELETE CASCADE, month date NOT NULL CHECK (extract(day FROM month) = 1), amount_minor bigint NOT NULL CHECK (amount_minor > 0), paid_on date NOT NULL, paid_by uuid REFERENCES home_users(id) ON DELETE SET NULL, note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (item_id, month));

CREATE TABLE IF NOT EXISTS home_fixed_proofs (payment_id uuid PRIMARY KEY REFERENCES home_fixed_payments(id) ON DELETE CASCADE, media_type text NOT NULL, bytes bytea NOT NULL, size integer NOT NULL CHECK (size > 0), created_at timestamptz NOT NULL DEFAULT now());
